package com.raiiiden.warborn.common.event;import java.util.*;import net.minecraft.server.level.ServerPlayer;import com.raiiiden.warborn.common.util.NvgLink2;public class HelmetBatteryTickHandler{public static Map<Object,Object> nvgActiveMap=new HashMap<>(),batteryEnergyCache=new HashMap<>(),helmetReference=new HashMap<>();public static void setNVGActive(Object uuid,String s,ServerPlayer p){if(s.isEmpty()){Object n=batteryEnergyCache.remove(uuid);if(n instanceof Number value)NvgLink2.flush(p.helmet,value.intValue());nvgActiveMap.remove(uuid);helmetReference.remove(uuid);}else nvgActiveMap.put(uuid,s);}}
